// Native regression harness: compile with KDAExteriorDepth.cs into an isolated
// KSP test copy with Resurfaced installed. Never install in a player game: this
// harness renders synthetic masked geometry and exits KSP after assertions.
// Not included by build_plugin.ps1. Requires Unity/KSP assemblies and UI.
using System;using System.Collections;using System.IO;using UnityEngine;using UnityEngine.Rendering;
[KSPAddon(KSPAddon.Startup.Instantly,true)]public class KDAExteriorDepthNativeTests:MonoBehaviour{
 void Awake(){DontDestroyOnLoad(gameObject);Application.runInBackground=true;}
 GameObject Quad(float z,Material m){var o=GameObject.CreatePrimitive(PrimitiveType.Quad);o.transform.position=new Vector3(0,0,z);var mesh=o.GetComponent<MeshFilter>().mesh;var colors=new Color[mesh.vertexCount];for(int i=0;i<colors.Length;i++)colors[i]=Color.white;mesh.colors=colors;o.GetComponent<Renderer>().sharedMaterial=m;return o;}
 float Read(RenderTexture rt,int x){RenderTexture.active=rt;var read=new Texture2D(64,64,TextureFormat.RGBAFloat,false,true);read.ReadPixels(new Rect(0,0,64,64),0,0);read.Apply();float v=read.GetPixel(x,32).r;Destroy(read);RenderTexture.active=null;return v;}
 IEnumerator Start(){yield return new WaitForEndOfFrame();var bundle=AssetBundle.LoadFromFile(Path.Combine(KSPUtil.ApplicationRootPath,"GameData/Resurfaced/stockalike_standard_shaders.shab"));Shader cut=null;foreach(var s in bundle.LoadAllAssets<Shader>())if(s.name=="Resurfaced/StandardAlphaTest")cut=s;
 var mask=new Texture2D(2,1,TextureFormat.RGBA32,false);mask.SetPixels(new[]{Color.clear,Color.white});mask.filterMode=FilterMode.Point;mask.Apply();
 var fm=new Material(cut);fm.mainTexture=mask;fm.color=Color.white;fm.SetFloat("_AlphaCutoff",.45f);fm.SetFloat("_Smoothness",0);fm.SetFloat("_Metalness",0);fm.SetTexture("_Emissive",Texture2D.whiteTexture);fm.SetColor("_EmissiveColor",new Color(0,1,0,1));fm.renderQueue=2550;var front=Quad(0,fm);
 var rearMat=new Material(Shader.Find("Standard"));rearMat.color=Color.red;var rear=Quad(.3f,rearMat);
 var body=new GameObject("KDA depth regression part").AddComponent<Part>();front.transform.SetParent(body.transform,true);KDAExteriorDepth.Ensure(body);var helper=body.GetComponent<KDAExteriorDepth>();Debug.Log("[DEPTHPROBE] native helper masked count="+helper.MaterialCount);if(helper.MaterialCount!=1)throw new Exception("Missing native depth companion");GameObject proxy=null;foreach(var rr in body.GetComponentsInChildren<MeshRenderer>())if(rr.gameObject!=front)proxy=rr.gameObject;if(proxy==null)throw new Exception("Missing native renderer");
 var cam=new GameObject("Depth probe camera").AddComponent<Camera>();cam.enabled=false;cam.transform.position=new Vector3(0,0,-2);cam.fieldOfView=45;cam.nearClipPlane=.1f;cam.farClipPlane=10;cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=Color.black;cam.depthTextureMode=DepthTextureMode.Depth;cam.allowMSAA=false;
 int checks=0;float originalColor=0;foreach(var path in new[]{RenderingPath.Forward,RenderingPath.DeferredShading})foreach(bool added in new[]{false,true}){
  cam.renderingPath=path;fm.renderQueue=path==RenderingPath.Forward?2550:2450;proxy.SetActive(added);var color=new RenderTexture(64,64,24,RenderTextureFormat.ARGBFloat);var rt=new RenderTexture(64,64,0,RenderTextureFormat.ARGBFloat);var cb=new CommandBuffer();cb.Blit(BuiltinRenderTextureType.Depth,rt);cam.AddCommandBuffer(CameraEvent.BeforeImageEffectsOpaque,cb);cam.targetTexture=color;cam.Render();float hole=Read(rt,24),solid=Read(rt,40),visible=Read(color,40);if(!added)originalColor=visible;else {if(Math.Abs(visible-originalColor)>.00001f)throw new Exception("Companion changed visible color");checks++;if(path==RenderingPath.Forward){if(Math.Abs(hole-.0338164f)>.0001f||Math.Abs(solid-.040404f)>.0001f)throw new Exception("Depth mask regression");checks+=2;}}Debug.Log("[DEPTHPROBE] "+path+" added="+added+" hole="+hole.ToString("F7")+" solid="+solid.ToString("F7")+" gap="+Math.Abs(hole-solid));cam.RemoveCommandBuffer(CameraEvent.BeforeImageEffectsOpaque,cb);cb.Release();cam.targetTexture=null;Destroy(color);Destroy(rt);
 }
 if(KDAExteriorDepth.ColorQueue(2550,false)!=2550||KDAExteriorDepth.ColorQueue(2550,true)!=2450||KDAExteriorDepth.ColorQueue(3000,true)!=3000||KDAExteriorDepth.NeedsDepth("Resurfaced/Standard",-1)||KDAExteriorDepth.NeedsDepth("Resurfaced/StandardAlphaBlend",-1)||KDAExteriorDepth.NeedsDepth("Resurfaced/StandardAlphaTest",2))throw new Exception("Scope regression");checks+=6;int before=body.GetComponentsInChildren<MeshRenderer>().Length;KDAExteriorDepth.Ensure(body);if(body.GetComponentsInChildren<MeshRenderer>().Length!=before)throw new Exception("Duplicate companion");checks++;if(front.GetComponent<Renderer>().sharedMaterial!=fm||fm.mainTexture!=mask)throw new Exception("Source material changed");checks++;Destroy(helper);Debug.Log("[DEPTHPROBE] PASS "+checks+" native assertions; COMPLETE");Application.Quit();
 }
}
